<script>

    let burger_menu=document.getElementById('burger_menu')
    function burger_menu_function( str ){
        console.log(str)
        // if(burger_menu.classList.contains("translate-x-[100%]")){
        if(str=="open"){
            burger_menu.classList.remove("translate-x-[100%]")
            burger_menu.children[0].classList.remove("translate-x-[100%]")
            burger_menu.children[1].classList.remove("translate-x-[100%]")
            burger_menu.classList.add("translate-x-.0")
            burger_menu.children[0].classList.add("translate-x-0")
            burger_menu.children[1].classList.add("translate-x-0")
        }else{
            burger_menu.classList.remove("translate-x-[0]")
            burger_menu.children[0].classList.remove("translate-x-[0]")
            burger_menu.children[1].classList.remove("translate-x-[0]")
            burger_menu.classList.add("translate-x-[100%]")
            burger_menu.children[0].classList.add("translate-x-[100%]")
            burger_menu.children[1].classList.add("translate-x-[100%]")
        }

    }
    function dropdown(el){
        if(!el.children[0].children[1].classList.contains("rotate-180")){
            el.children[0].children[1].classList.remove("rotate-0")
            el.children[0].children[1].classList.add("rotate-180")
            el.children[1].classList.add("h-[100px]")
        }else{
            el.children[0].children[1].classList.remove("rotate-180")
            el.children[0].children[1].classList.add("rotate-0")
            el.children[1].classList.add("h-0")
            el.children[1].classList.remove("h-[100px]")
        }
    }



    let Portfolios =document.querySelectorAll('.Portfolios')
    function show_portofilos(){
        Portfolios.forEach(Portfolio => {
            if(Portfolio.classList.contains('bg-[var(--color-primary-3rd)]')){
                Portfolio.classList.remove('bg-[var(--color-primary-3rd)]')
                Portfolio.classList.add('bg-[var(--color-gray-2)]')

            }
        })
    }
    Portfolios.forEach(Portfolio => {

        Portfolio.addEventListener('click',()=>{

        Portfolio.classList.remove('bg-[var(--color-gray-2)]')
        Portfolio.classList.add('bg-[var(--color-primary-3rd)]')
        })

        
    });



    // const card = document.querySelector(".card");

    // card.addEventListener("mousemove", (e) => {
    // const rect = card.getBoundingClientRect();

    // card.style.setProperty("--x", `${e.clientX - rect.left}px`);
    // card.style.setProperty("--y", `${e.clientY - rect.top}px`);
    // });

    // card.addEventListener("mouseleave", () => {
    // card.style.setProperty("--x", "50%");
    // card.style.setProperty("--y", "50%");
    // });

    document.querySelectorAll(".card").forEach(card => {
        card.addEventListener("mousemove", (e) => {
            const rect = card.getBoundingClientRect();

            card.style.setProperty("--x", `${e.clientX - rect.left}px`);
            card.style.setProperty("--y", `${e.clientY - rect.top}px`);
        });

        card.addEventListener("mouseleave", () => {
            card.style.setProperty("--x", "50%");
            card.style.setProperty("--y", "50%");
        });
    });




/// دیویژن های معلق





    const container = document.getElementById('container');
    const floating = document.getElementById('floating');
    const boxes = document.querySelectorAll('.my-box');

    // تابع برای قرار دادن دیویژن معلق دقیقاً پشت دیویژن مورد نظر
    function positionFloatingBehind(box) {
        const containerRect = container.getBoundingClientRect();
        const boxRect = box.getBoundingClientRect();
        
        // محاسبه موقعیت دقیق نسبت به کانتینر
        const left = boxRect.left - containerRect.left;
        const top = boxRect.top - containerRect.top;
        
        // تنظیم موقعیت دقیق
        floating.style.left = left + 'px';
        floating.style.top = top + 'px';
        floating.style.width = boxRect.width + 'px';
        floating.style.height = boxRect.height + 'px';
        floating.style.borderRadius = getComputedStyle(box).borderRadius;
        box.children[0].children[0].classList.remove('bg-[var(--color-gray-2)]');
        box.children[0].children[0].classList.add('bg-[var(--color-primary-3rd)]');
        // box.children[0].children[1].classList.add('text-[var(--color-primary-3rd)]');
        box.children[1].classList.remove('border-[var(--color-white)]');
        box.children[1].classList.add('border-[var(--color-primary-3rd)]');
        // box.children[2].classList.add('text-[var(--color-primary-3rd)]');

    }
    function positionFloatingBehindSetColor(box){
        box.children[0].children[0].classList.remove('bg-[var(--color-primary-3rd)]');
        box.children[0].children[0].classList.add('bg-[var(--color-gray-2)]');
        // box.children[0].children[1].classList.remove('text-[var(--color-primary-3rd)]');
        box.children[1].classList.remove('border-[var(--color-primary-3rd)]');
        box.children[1].classList.add('border-[var(--color-white)]');
        // box.children[2].classList.remove('text-[var(--color-primary-3rd)]');
    }

    // هاور روی هر دیویژن
    boxes.forEach((box) => {
        box.addEventListener('mouseenter', function() {
            positionFloatingBehind(this);
        });
        box.addEventListener('mouseleave', function() {
            positionFloatingBehindSetColor(this);
        });
    });

    // خروج موس از کانتینر - بره پشت اولین دیویژن
    // container.addEventListener('mouseleave', function() {
    //     if (boxes.length > 0) {
    //         positionFloatingBehind(boxes[0]);
    //     }
    // });

    // تنظیم اولیه - پشت اولین دیویژن
    window.addEventListener('load', function() {
        if (boxes.length > 0) {
            positionFloatingBehind(boxes[0]);
        }
    });

    // اگر صفحه از قبل لود شده بود
    if (document.readyState === 'complete') {
        if (boxes.length > 0) {
            positionFloatingBehind(boxes[0]);
        }
    }

    // بروزرسانی موقعیت هنگام تغییر سایز
    let resizeTimer;
    window.addEventListener('resize', function() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
            // بررسی کنیم کدام دیویژن در حال هاور است
            let hovered = null;
            boxes.forEach(box => {
                if (box.matches(':hover')) {
                    hovered = box;
                }
            });
            if (hovered) {
                positionFloatingBehind(hovered);
            } else if (boxes.length > 0) {
                positionFloatingBehind(boxes[0]);
            }
        }, 100);
    });




// حرکت قسمت نظرات

    let dots = document.querySelectorAll('.dot');
    let slids = document.querySelectorAll('.slide');
    let slidersWapper = document.querySelector('.slides-wrapper');
    let currentIndex=0;
    let totalSlides = slids.length;

    function doTransform(index){
    slidersWapper.style.transform=`translateX(${index * 100}%)`
        dots.forEach((dot , i) => {
            if(i==index){
                dot.classList.add('active')
            }else{
                dot.classList.remove('active')
            } 
        })  
    }
    dots.forEach((dot , i) => {
        dot.addEventListener('click',function(){
            currentIndex=i;
            doTransform(currentIndex)
        })
    });
    let autoPlay = setInterval(() => {
        currentIndex = (currentIndex + 1) % totalSlides;
        doTransform(currentIndex);
    }, 3000);

    function resetAutoPlay() {
        clearInterval(autoPlay);
        autoPlay = setInterval(() => {
            currentIndex = (currentIndex + 1) % totalSlides;
            doTransform(currentIndex);
        }, 3000);
    }
    dots.forEach(dot => dot.addEventListener('click', resetAutoPlay));

    doTransform(currentIndex)




    let inputs =document.querySelectorAll('.inputs');
    let spans =document.querySelectorAll('.spans');
    let spanLength= spans.length;
    inputs.forEach((input,i) => {
        spans[i].addEventListener('click',function(){
            inputs.forEach((input,i) => {
                input.classList.remove('border-[var(--color-primary-3rd)]')
                input.classList.add('border-gray-600');
                input.classList.remove('border-3');
                input.classList.add('border-1');
                spans[i].classList.remove('-top-4');
                spans[i].classList.add('top-5');
            });
            input.classList.remove('border-gray-600');
            input.classList.add('border-[var(--color-primary-3rd)]');
            input.classList.add('border-3');
            input.focus();
            spans[i].classList.remove('top-5');
            spans[i].classList.add('-top-3');


        })
        input.addEventListener('click',function(){
            inputs.forEach((input,i) => {
                input.classList.remove('border-[var(--color-primary-3rd)]')
                input.classList.add('border-gray-600');
                input.classList.remove('border-3');
                input.classList.add('border-1');
                spans[i].classList.remove('-top-4');
                spans[i].classList.add('top-5');
            });
            input.classList.remove('border-gray-600');
            input.classList.add('border-[var(--color-primary-3rd)]');
            input.classList.add('border-3');
            spans[i].classList.remove('top-5');
            spans[i].classList.add('-top-3');

        })
    });






    document.addEventListener('DOMContentLoaded', function () {
        var filterButtons = document.querySelectorAll('.Portfolios');
        var items = document.querySelectorAll('.portfolio-item');

        // اضافه کردن کلاس پایه برای انیمیشن
        items.forEach(function (item) {
            item.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
        });

        filterButtons.forEach(function (btn) {
            btn.addEventListener('click', function () {
                var filter = btn.getAttribute('data-filter');

                // تغییر استایل دکمه‌ها
                filterButtons.forEach(function (b) {
                    b.classList.remove('bg-[var(--color-primary-3rd)]');
                    b.classList.add('bg-[var(--color-gray-2)]');
                });
                btn.classList.remove('bg-[var(--color-gray-2)]');
                btn.classList.add('bg-[var(--color-primary-3rd)]');

                // مرحله ۱: محو کردن همه کارت‌ها
                items.forEach(function (item) {
                    item.style.opacity = '0';
                    item.style.transform = 'scale(0.95)';
                });

                // مرحله ۲: بعد از تموم شدن محو شدن، فیلتر کن و دوباره نشون بده
                setTimeout(function () {
                    items.forEach(function (item) {
                        if (filter === 'all' || item.classList.contains(filter)) {
                            item.style.display = '';
                            // یه تاخیر خیلی کوتاه برای رندر شدن
                            requestAnimationFrame(function () {
                                item.style.opacity = '1';
                                item.style.transform = 'scale(1)';
                            });
                        } else {
                            item.style.display = 'none';
                        }
                    });
                }, 400); // این عدد باید با مدت زمان transition بالا یکی باشه
            });
        });
    });


    

</script>








